import React, { useState, useEffect } from 'react';

function CustomerDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [services, setServices] = useState([]);
  const [vehicles, setVehicles] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [onlineDrivers, setOnlineDrivers] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showBookingModal, setShowBookingModal] = useState(false);
  const [selectedService, setSelectedService] = useState(null);
  const [showVehicleModal, setShowVehicleModal] = useState(false);
  const [filters, setFilters] = useState({ category: 'all', search: '', minPrice: '', maxPrice: '' });

  const [bookingData, setBookingData] = useState({
    date: '', time: '', vehicleId: '', isConcierge: false, pickupAddress: '', notes: ''
  });

  const [newVehicle, setNewVehicle] = useState({
    make: '', model: '', year: '', licensePlate: '', color: ''
  });

  const token = localStorage.getItem('token');

  // Real-time data fetching
  useEffect(() => {
    fetchAllData();
    const interval = setInterval(() => {
      fetchOnlineDrivers();
      fetchBookings();
    }, 10000); // Refresh every 10 seconds
    return () => clearInterval(interval);
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      await Promise.all([
        fetchServices(),
        fetchVehicles(),
        fetchBookings(),
        fetchOnlineDrivers(),
        fetchCategories()
      ]);
    } catch (error) {
      console.error('Error fetching data:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchServices = async () => {
    let url = 'http://localhost:5000/api/services?';
    if (filters.category && filters.category !== 'all') url += `category=${filters.category}&`;
    if (filters.search) url += `search=${filters.search}&`;
    if (filters.minPrice) url += `minPrice=${filters.minPrice}&`;
    if (filters.maxPrice) url += `maxPrice=${filters.maxPrice}&`;

    const res = await fetch(url);
    const data = await res.json();
    if (data.success) setServices(data.services);
  };

  const fetchVehicles = async () => {
    const res = await fetch('http://localhost:5000/api/services/customer/vehicles', {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    const data = await res.json();
    if (data.success) setVehicles(data.vehicles);
  };

  const fetchBookings = async () => {
    const res = await fetch('http://localhost:5000/api/services/customer/bookings', {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    const data = await res.json();
    if (data.success) setBookings(data.bookings);
  };

  const fetchOnlineDrivers = async () => {
    const res = await fetch('http://localhost:5000/api/driver/online');
    const data = await res.json();
    if (data.success) setOnlineDrivers(data.drivers);
  };

  const fetchCategories = async () => {
    const res = await fetch('http://localhost:5000/api/services/public/categories');
    const data = await res.json();
    if (data.success) setCategories(data.categories);
  };

  const addVehicle = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:5000/api/services/customer/vehicles', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(newVehicle)
      });
      const data = await res.json();
      if (data.success) {
        alert('Vehicle added!');
        setShowVehicleModal(false);
        setNewVehicle({ make: '', model: '', year: '', licensePlate: '', color: '' });
        fetchVehicles();
      }
    } catch (error) {
      alert('Failed to add vehicle');
    }
  };

  const createBooking = async () => {
    if (!bookingData.date || !bookingData.time) {
      alert('Please select date and time');
      return;
    }
    if (vehicles.length === 0 && !bookingData.vehicleId) {
      alert('Please add a vehicle first');
      setShowVehicleModal(true);
      return;
    }

    try {
      const res = await fetch('http://localhost:5000/api/services/customer/bookings', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          serviceId: selectedService._id,
          vehicleId: bookingData.vehicleId || vehicles[0]?._id,
          bookingDate: bookingData.date,
          bookingTime: bookingData.time,
          isConcierge: bookingData.isConcierge,
          pickupAddress: bookingData.pickupAddress,
          notes: bookingData.notes
        })
      });
      const data = await res.json();
      if (data.success) {
        alert('Booking created successfully!');
        setShowBookingModal(false);
        setSelectedService(null);
        setBookingData({ date: '', time: '', vehicleId: '', isConcierge: false, pickupAddress: '', notes: '' });
        fetchBookings();
      }
    } catch (error) {
      alert('Failed to create booking');
    }
  };

  const cancelBooking = async (bookingId) => {
    if (window.confirm('Cancel this booking?')) {
      try {
        const res = await fetch(`http://localhost:5000/api/services/customer/bookings/${bookingId}/cancel`, {
          method: 'PUT',
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const data = await res.json();
        if (data.success) {
          alert('Booking cancelled');
          fetchBookings();
        }
      } catch (error) {
        alert('Failed to cancel');
      }
    }
  };

  const getStatusBadge = (status) => {
    const colors = {
      pending: '#f59e0b',
      confirmed: '#10b981',
      'in-progress': '#3b82f6',
      completed: '#8b5cf6',
      cancelled: '#ef4444',
      'driver-assigned': '#8b5cf6',
      pickup: '#3b82f6',
      'en-route': '#10b981'
    };
    const labels = {
      pending: '⏳ Pending',
      confirmed: '✓ Confirmed',
      'in-progress': '🔧 In Progress',
      completed: '✅ Completed',
      cancelled: '❌ Cancelled',
      'driver-assigned': '🚗 Driver Assigned',
      pickup: '📍 Pickup',
      'en-route': '🚚 En Route'
    };
    return { backgroundColor: colors[status] || '#6b7280', color: 'white', padding: '4px 12px', borderRadius: '20px', fontSize: '12px', display: 'inline-block' };
  };

  return (
    <div style={styles.dashboard}>
      {/* Header */}
      <div style={styles.header}>
        <div style={styles.logoSection}>
          <span style={styles.logoIcon}>🚗💨</span>
          <h1 style={styles.logoText}>Car Care Connect</h1>
        </div>
        <div style={styles.headerStats}>
          <span style={styles.headerStat}>🚗 {onlineDrivers.length} Drivers Online</span>
          <span style={styles.headerStat}>📅 {bookings.filter(b => b.status === 'pending').length} Pending</span>
        </div>
        <div style={styles.userInfo}>
          <span>👤 {user.firstName} {user.lastName}</span>
          <button onClick={onLogout} style={styles.logoutButton}>Logout</button>
        </div>
      </div>

      {/* Live Drivers Bar */}
      {onlineDrivers.length > 0 && (
        <div style={styles.liveDriversBar}>
          <span style={styles.liveDot}>●</span>
          <span>Live: </span>
          {onlineDrivers.slice(0, 5).map(driver => (
            <span key={driver._id} style={styles.driverTag}>
              🚗 {driver.firstName} {driver.vehicleModel ? `(${driver.vehicleModel})` : ''}
            </span>
          ))}
          {onlineDrivers.length > 5 && <span>+{onlineDrivers.length - 5} more</span>}
        </div>
      )}

      {/* Stats Cards */}
      <div style={styles.statsGrid}>
        <div style={styles.statCard}><h3>🚗 Vehicles</h3><p style={styles.statNumber}>{vehicles.length}</p><button style={styles.smallBtn} onClick={() => setShowVehicleModal(true)}>+ Add</button></div>
        <div style={styles.statCard}><h3>📅 Bookings</h3><p style={styles.statNumber}>{bookings.length}</p></div>
        <div style={styles.statCard}><h3>✅ Completed</h3><p style={styles.statNumber}>{bookings.filter(b => b.status === 'completed').length}</p></div>
        <div style={styles.statCard}><h3>🚗 Drivers</h3><p style={styles.statNumber}>{onlineDrivers.length}</p></div>
      </div>

      {/* Tabs */}
      <div style={styles.tabs}>
        <button style={{...styles.tab, ...(activeTab === 'dashboard' ? styles.activeTab : {})}} onClick={() => setActiveTab('dashboard')}>📊 Dashboard</button>
        <button style={{...styles.tab, ...(activeTab === 'services' ? styles.activeTab : {})}} onClick={() => { fetchServices(); setActiveTab('services'); }}>🔧 Services</button>
        <button style={{...styles.tab, ...(activeTab === 'vehicles' ? styles.activeTab : {})}} onClick={() => setActiveTab('vehicles')}>🚗 My Vehicles</button>
        <button style={{...styles.tab, ...(activeTab === 'bookings' ? styles.activeTab : {})}} onClick={() => setActiveTab('bookings')}>📅 My Bookings</button>
        <button style={{...styles.tab, ...(activeTab === 'drivers' ? styles.activeTab : {})}} onClick={() => setActiveTab('drivers')}>🚗 Live Drivers</button>
      </div>

      {/* Content */}
      <div style={styles.content}>
        {loading ? <div style={styles.loading}>Loading...</div> : (
          <>
            {/* Dashboard Tab */}
            {activeTab === 'dashboard' && (
              <div>
                <div style={styles.welcomeCard}>
                  <h2>Welcome back, {user.firstName}! 👋</h2>
                  <p>What service do you need today?</p>
                  <button style={styles.bookNowBtn} onClick={() => setActiveTab('services')}>Book a Service →</button>
                </div>

                {bookings.filter(b => b.status !== 'completed' && b.status !== 'cancelled').length > 0 && (
                  <div style={styles.card}>
                    <h3>📋 Active Bookings</h3>
                    {bookings.filter(b => b.status !== 'completed' && b.status !== 'cancelled').slice(0, 3).map(booking => (
                      <div key={booking._id} style={styles.activeBooking}>
                        <div><strong>{booking.serviceName}</strong> - {new Date(booking.bookingDate).toLocaleDateString()}</div>
                        <span style={getStatusBadge(booking.status)}>{booking.status}</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* Services Tab */}
            {activeTab === 'services' && (
              <div>
                {/* Filters */}
                <div style={styles.filtersBar}>
                  <select style={styles.filterSelect} value={filters.category} onChange={(e) => setFilters({...filters, category: e.target.value})}>
                    <option value="all">All Categories</option>
                    {categories.map(cat => <option key={cat._id} value={cat._id}>{cat._id}</option>)}
                  </select>
                  <input style={styles.filterInput} type="text" placeholder="Search services..." value={filters.search} onChange={(e) => setFilters({...filters, search: e.target.value})} />
                  <input style={styles.filterInputSmall} type="number" placeholder="Min $" value={filters.minPrice} onChange={(e) => setFilters({...filters, minPrice: e.target.value})} />
                  <input style={styles.filterInputSmall} type="number" placeholder="Max $" value={filters.maxPrice} onChange={(e) => setFilters({...filters, maxPrice: e.target.value})} />
                  <button style={styles.filterBtn} onClick={fetchServices}>Apply</button>
                </div>

                <div style={styles.servicesGrid}>
                  {services.map(service => (
                    <div key={service._id} style={styles.serviceCard}>
                      <h3>{service.name}</h3>
                      <p style={styles.providerName}>🔧 {service.providerBusinessName || service.providerName}</p>
                      <p>{service.description.substring(0, 100)}...</p>
                      <div style={styles.servicePrice}>
                        <span style={styles.price}>${service.price}</span>
                        <span style={styles.duration}>⏱️ {service.duration} min</span>
                      </div>
                      <div style={styles.serviceRating}>
                        <span>⭐ {service.rating || 4.5}</span>
                        <span>📊 {service.totalBookings || 0} bookings</span>
                      </div>
                      <button style={styles.bookBtn} onClick={() => { setSelectedService(service); setShowBookingModal(true); }}>Book Now →</button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Vehicles Tab */}
            {activeTab === 'vehicles' && (
              <div>
                <button style={styles.addVehicleBtn} onClick={() => setShowVehicleModal(true)}>+ Add Vehicle</button>
                {vehicles.length === 0 ? (
                  <div style={styles.emptyState}>No vehicles added. Add your first vehicle!</div>
                ) : (
                  vehicles.map(vehicle => (
                    <div key={vehicle._id} style={styles.vehicleCard}>
                      <div><strong>{vehicle.year} {vehicle.make} {vehicle.model}</strong></div>
                      <div>License: {vehicle.licensePlate} | Color: {vehicle.color || 'N/A'}</div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Bookings Tab */}
            {activeTab === 'bookings' && (
              <div>
                {bookings.length === 0 ? (
                  <div style={styles.emptyState}>No bookings yet. Book your first service!</div>
                ) : (
                  bookings.map(booking => (
                    <div key={booking._id} style={styles.bookingCard}>
                      <div style={styles.bookingHeader}>
                        <div>
                          <h3>{booking.serviceName}</h3>
                          <p>Provider: {booking.providerId?.businessName || booking.providerId?.firstName}</p>
                        </div>
                        <span style={getStatusBadge(booking.status)}>{booking.status}</span>
                      </div>
                      <div style={styles.bookingDetails}>
                        <span>📅 {new Date(booking.bookingDate).toLocaleDateString()}</span>
                        <span>⏰ {booking.bookingTime}</span>
                        <span>💰 ${booking.totalAmount}</span>
                      </div>
                      {booking.driverId && (
                        <div style={styles.driverInfo}>
                          <span>🚗 Driver: {booking.driverId?.firstName} {booking.driverId?.lastName}</span>
                          {booking.driverLocation?.lat && <span>📍 Live tracking available</span>}
                        </div>
                      )}
                      {(booking.status === 'pending' || booking.status === 'confirmed') && (
                        <button style={styles.cancelBookingBtn} onClick={() => cancelBooking(booking._id)}>Cancel Booking</button>
                      )}
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Live Drivers Tab */}
            {activeTab === 'drivers' && (
              <div>
                <div style={styles.liveAlert}>
                  <span style={styles.liveDot}>●</span> {onlineDrivers.length} Drivers currently online and available
                </div>
                <div style={styles.driversGrid}>
                  {onlineDrivers.map(driver => (
                    <div key={driver._id} style={styles.driverCard}>
                      <div style={styles.driverAvatar}>🚗</div>
                      <h3>{driver.firstName} {driver.lastName}</h3>
                      <div style={styles.driverInfo}>
                        <span>⭐ {driver.rating || 5.0}</span>
                        <span>📦 {driver.totalDeliveries || 0} deliveries</span>
                      </div>
                      <div style={styles.driverVehicle}>
                        {driver.vehicleModel && <span>{driver.vehicleModel} {driver.vehicleColor}</span>}
                      </div>
                      <span style={styles.onlineBadge}>● Online</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </>
        )}
      </div>

      {/* Booking Modal */}
      {showBookingModal && selectedService && (
        <div style={styles.modal}>
          <div style={styles.modalContent}>
            <h2>Book {selectedService.name}</h2>
            <p>Provider: {selectedService.providerBusinessName}</p>
            <p>Price: ${selectedService.price}</p>

            <label>Select Vehicle:</label>
            <select style={styles.input} value={bookingData.vehicleId} onChange={(e) => setBookingData({...bookingData, vehicleId: e.target.value})}>
              <option value="">Select a vehicle</option>
              {vehicles.map(v => <option key={v._id} value={v._id}>{v.year} {v.make} {v.model}</option>)}
            </select>

            <label>Select Date:</label>
            <input type="date" style={styles.input} value={bookingData.date} onChange={(e) => setBookingData({...bookingData, date: e.target.value})} min={new Date().toISOString().split('T')[0]} />

            <label>Select Time:</label>
            <input type="time" style={styles.input} value={bookingData.time} onChange={(e) => setBookingData({...bookingData, time: e.target.value})} />

            <label style={styles.checkboxLabel}>
              <input type="checkbox" checked={bookingData.isConcierge} onChange={(e) => setBookingData({...bookingData, isConcierge: e.target.checked})} />
              🚗 Need Concierge Driver? (Driver picks up & returns your vehicle)
            </label>

            {bookingData.isConcierge && (
              <>
                <label>Pickup Address:</label>
                <textarea style={styles.textarea} placeholder="Enter pickup address" value={bookingData.pickupAddress} onChange={(e) => setBookingData({...bookingData, pickupAddress: e.target.value})} />
              </>
            )}

            <label>Special Instructions (Optional):</label>
            <textarea style={styles.textarea} placeholder="Any special instructions for the provider?" value={bookingData.notes} onChange={(e) => setBookingData({...bookingData, notes: e.target.value})} />

            <div style={styles.modalActions}>
              <button style={styles.submitBtn} onClick={createBooking}>Confirm Booking</button>
              <button style={styles.cancelBtn} onClick={() => { setShowBookingModal(false); setSelectedService(null); }}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      {/* Vehicle Modal */}
      {showVehicleModal && (
        <div style={styles.modal}>
          <div style={styles.modalContentSmall}>
            <h2>Add Vehicle</h2>
            <form onSubmit={addVehicle}>
              <input style={styles.input} placeholder="Make (e.g., Toyota)" value={newVehicle.make} onChange={(e) => setNewVehicle({...newVehicle, make: e.target.value})} required />
              <input style={styles.input} placeholder="Model (e.g., Camry)" value={newVehicle.model} onChange={(e) => setNewVehicle({...newVehicle, model: e.target.value})} required />
              <input style={styles.input} type="number" placeholder="Year" value={newVehicle.year} onChange={(e) => setNewVehicle({...newVehicle, year: e.target.value})} required />
              <input style={styles.input} placeholder="License Plate" value={newVehicle.licensePlate} onChange={(e) => setNewVehicle({...newVehicle, licensePlate: e.target.value})} required />
              <input style={styles.input} placeholder="Color" value={newVehicle.color} onChange={(e) => setNewVehicle({...newVehicle, color: e.target.value})} />
              <div style={styles.modalActions}>
                <button type="submit" style={styles.submitBtn}>Save</button>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowVehicleModal(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

